    case "symdex.prelude.Relation1" => true
    case "symdex.prelude.Relation2" => true
    case _ => false
  }
}

def needsSeed(relation: String): Boolean = {
  relation match {
    case "symdex.+" | "symdex.==" | "symdex.!=" | "symdex.<" | "symdex.>" | "symdex.<= " | "symdex.>= " => true
    case _ => false
  }
