def listTmp(): Either[String, Ran] = {
  val process = Exec.runProcess("ls", Seq("/tmp"), timeout = 5 seconds)
  process.map {
    case (exitCode, output) =>
      if (exitCode == 0) Right(Ran(output))
      else Left(s"Command failed with exit code $exitCode")
  }.getOrElse(Left("Process execution failed"))
}

