object Equivalence {
  def sameBehaviour(out: String): Boolean = {
    val lines = out.split("
")
    for (line <- lines) {
      if (line.contains("Equivalence")) {
        val parts = line.split(" ")
        if (parts.length >= 2 && parts(1) == "equivalent") {
          return true
        }
      }
    }
    false
  }
}

