def listTmp(): Either[String, Ran] = {
  val process = Run("ls", "/tmp", Seq())
  val answered = process.answered
  val real = process.real
  val run = process.run
  Either.catchAll {
    run.timeout(5 seconds).either
  } {
    case e: Exception => Left(e.getMessage)
  }
}

